def deleteAndEarn(nums):
    if not nums:
        return 0

    # Build points: points[x] = x × frequency of x in nums
    max_num = max(nums)
    points = [0] * (max_num + 1)
    for num in nums:
        points[num] += num

    # Now, classic house robber DP
    take, skip = 0, 0
    for value in points:
        take, skip = skip + value, max(skip, take)
    return max(take, skip)
